import{_ as e,o as a,c as n,a2 as t}from"./chunks/framework.doxMM-x8.js";const u=JSON.parse('{"title":"Install a fixed scene and manage a Simulation Session","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/simulation-session","contentType":"tutorial","prev":{"text":"Synthetic motion and two Viewers","link":"/en/tutorials/synthetic-motion"},"next":{"text":"Spatial workbench","link":"/en/tutorials/spatial-workbench"}},"headers":[],"relativePath":"en/tutorials/simulation-session.md","filePath":"en/tutorials/simulation-session.md"}'),i={name:"en/tutorials/simulation-session.md"};function o(r,s,l,p,c,d){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="install-a-fixed-scene-and-manage-a-simulation-session" tabindex="-1">Install a fixed scene and manage a Simulation Session <a class="header-anchor" href="#install-a-fixed-scene-and-manage-a-simulation-session" aria-label="Permalink to &quot;Install a fixed scene and manage a Simulation Session&quot;">​</a></h1><p>Goal: explicitly run one fixed scene and observe the same Simulation Session in two desktop Viewers. Each Viewer keeps its camera, selection, and Inspector.</p><p>Complete <a href="./persistent-world">Persistent Labs and objects</a> and <a href="./persistent-assets">Persistent digital assets</a> first. Use the repository Node and pnpm versions, Python 3.10+ with venv and pip, and Linux or WSL Ubuntu. Run Bash commands from the repository root. They create isolated development data. This chapter uses development synthetic motion. It needs no GPU, Newton, or Docker. Reliable Lab Recording remains a later capability.</p><h2 id="configure-the-owned-source" tabindex="-1">Configure the owned source <a class="header-anchor" href="#configure-the-owned-source" aria-label="Permalink to &quot;Configure the owned source&quot;">​</a></h2><p>Stop your previous development instance with Ctrl+C. Create the Python environment and start the application:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/session-python</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.scratch/session-python/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/synthetic-motion/requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAB_WORD_SYNTHETIC_SESSION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_WORD_SYNTHETIC_PYTHON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.scratch/session-python/bin/python&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_WORD_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.scratch/session-tutorial-data</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Open <a href="http://127.0.0.1:5173/lab" target="_blank" rel="noreferrer">http://127.0.0.1:5173/lab</a>. Register or sign in as an ordinary Member. Create an empty Lab named <code>Shared Session</code>. Import <code>tests/fixtures/lab/cube.glb</code> in the asset library, with its source, license, and version. Return to the Lab. The installation picker uses the saved asset library and needs no existing Lab object.</p><p>Normal Node/Web startup and builds need no Python. The explicit setting enables the loopback development source. The server starts Python only after Start. Its <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/apps/server/src/synthetic-source.ts" target="_blank" rel="noreferrer">source supervisor</a> owns the process, stdin pipe, and cleanup ledger. It sends the fixed startup conditions once and holds the pipe open. Do not run <code>publisher.py --startup-stdin</code> manually. The separate <a href="./synthetic-motion">synthetic fixture tutorial</a> keeps its own explicit launch contract.</p><h2 id="install-and-start" tabindex="-1">Install and Start <a class="header-anchor" href="#install-and-start" aria-label="Permalink to &quot;Install and Start&quot;">​</a></h2><ol><li>Open <strong>Simulation Session</strong>.</li><li>Select your imported asset under <strong>GLB model</strong>. Use <strong>Load more</strong> if it is on a later page. If the list fails, use <strong>Retry GLB models</strong>.</li><li>Click <strong>Install fixed scene</strong>.</li><li>Select the resulting <strong>Scene Installation</strong> and keep <code>30 Hz</code>.</li><li>Click <strong>Start</strong>.</li><li>Wait for <strong>Running</strong> and <strong>Motion connected</strong>. Close the dialog.</li></ol><p>The fixed package is <code>development-synthetic@1</code>. Installation creates 20 independent Entities and Scene Nodes, with six joint keys. A second Installation creates different object identities. This chapter does not upgrade packages or create a business Entity for each robot link.</p><p>Start fixes the actual saved layout, Installation, assets, parameters, and initial state. The first source frame reproduces that initial state. <strong>Starting</strong> means the server is waiting for it. The server allocates a machine identity, a unique Publisher lease, and its epoch. The Viewer cannot choose an epoch or replace the Publisher.</p><p>Open the same Lab in a second browser tab. The Viewer automatically observes the active Session. Open <strong>Simulation Session</strong> and select <code>15 Hz</code>. Rotate its camera and select another Entity. Both Viewers show the same Session UUID and source state. Camera and Inspector choices stay independent. <strong>Leave observation</strong> closes only that Viewer subscription. <strong>Observe Session</strong> obtains a fresh ticket. <strong>Close</strong> keeps observation open.</p><h2 id="pause-and-resume" tabindex="-1">Pause and Resume <a class="header-anchor" href="#pause-and-resume" aria-label="Permalink to &quot;Pause and Resume&quot;">​</a></h2><ol><li>Click <strong>Pause</strong> in either Viewer.</li><li>Wait for <strong>Paused · simulation time and pose frozen</strong>.</li><li>Keep both Viewers open for several seconds. Open a third tab during Pause.</li><li>Confirm that all three display the same frozen pose.</li><li>Click <strong>Resume</strong> and wait for <strong>Running</strong>.</li></ol><p><strong>Pausing</strong> and <strong>Resuming</strong> are accepted requests, not completed source actions. The source sends a new complete boundary frame and a correlated acknowledgement. Pause displays that exact boundary, including at <code>15 Hz</code>. It does not freeze an older interpolated pose. The simulation clock stays fixed while heartbeat continues. A paused late join receives the fixed mapping and complete cached pose.</p><p>Resume excludes paused wall time. Its trusted boundary starts a new receive-clock segment. Sequence stays increasing within the server epoch. The Viewer does not interpolate across Pause or use duplicate WELCOME to reset its buffer. Motion reception freshness, connection health, and Session lifecycle remain separate.</p><h2 id="compare-reset-and-the-next-start" tabindex="-1">Compare Reset and the next Start <a class="header-anchor" href="#compare-reset-and-the-next-start" aria-label="Permalink to &quot;Compare Reset and the next Start&quot;">​</a></h2><ol><li>Pause the Session and note its UUID.</li><li>Close the dialog. Select an installed object and open <strong>Edit layout</strong>.</li><li>Change its X Placement and scale, then save the layout.</li><li>Return to <strong>Runtime</strong>. The Session still uses the original fixed geometry and pose.</li><li>Open <strong>Simulation Session</strong> and click <strong>Reset</strong>.</li><li>Wait for the new Session to run. Its UUID changes; its startup snapshot remains the original snapshot.</li><li>Click <strong>Stop</strong> and wait for <strong>Stopped</strong>. The Viewer returns to the latest saved layout.</li><li>Click <strong>Start</strong>. This ordinary Start uses the newly saved Placement and scale.</li></ol><p>The layout editor previews the next Start. Saving leaves the active simulation fixed. Reset ends and fences the old Session, clears Viewer buffers, and obtains new Session-bound tickets and mapping. It preserves saved Placement and Registered Location. An active Installation cannot silently change object ownership or asset bindings. A refused structural edit leaves it unchanged. Other Lab objects and Device Program Runs retain their own behavior. The Inspector reads live Entity facts.</p><h2 id="check-conflict-and-denial" tabindex="-1">Check conflict and denial <a class="header-anchor" href="#check-conflict-and-denial" aria-label="Permalink to &quot;Check conflict and denial&quot;">​</a></h2><p>Keep the Session running or paused. Stop controls in other tabs. In the authenticated Lab page&#39;s browser Console, list the Lab UUIDs:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/api/v1/lab/labs&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()).data.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(({ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  id,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  name,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}));</span></span></code></pre></div><p>Paste the complete function below into that Console. Then call <code>await checkSessionRefusals(&#39;&lt;lab-uuid&gt;&#39;)</code> with the <code>Shared Session</code> UUID:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Paste into the Console of the authenticated, same-origin Lab page.</span></span>
<span class="line"><span>// Call with a Lab UUID whose Session is running or paused. Neither action is accepted.</span></span>
<span class="line"><span>globalThis.checkSessionRefusals = async function checkSessionRefusals(labId) {</span></span>
<span class="line"><span>  const read = async () =&gt; {</span></span>
<span class="line"><span>    const response = await fetch(\`/api/v1/lab/labs/\${labId}/sessions\`);</span></span>
<span class="line"><span>    if (!response.ok)</span></span>
<span class="line"><span>      throw new Error(\`Session list failed: \${response.status}\`);</span></span>
<span class="line"><span>    const page = await response.json();</span></span>
<span class="line"><span>    return page.data.find((session) =&gt; session.id === page.active_session_id);</span></span>
<span class="line"><span>  };</span></span>
<span class="line"><span>  const before = await read();</span></span>
<span class="line"><span>  if (</span></span>
<span class="line"><span>    !before ||</span></span>
<span class="line"><span>    ![&#39;running&#39;, &#39;paused&#39;].includes(before.status) ||</span></span>
<span class="line"><span>    before.revision &lt; 1</span></span>
<span class="line"><span>  )</span></span>
<span class="line"><span>    throw new Error(</span></span>
<span class="line"><span>      &#39;Start or Pause a Session, wait for its final state, then retry.&#39;,</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>  const identityResponse = await fetch(&#39;/api/v1/auth/session&#39;);</span></span>
<span class="line"><span>  if (!identityResponse.ok) throw new Error(&#39;Sign in before this check.&#39;);</span></span>
<span class="line"><span>  const identity = await identityResponse.json();</span></span>
<span class="line"><span>  const action = before.status === &#39;paused&#39; ? &#39;resume&#39; : &#39;pause&#39;;</span></span>
<span class="line"><span>  const path = \`/api/v1/lab/labs/\${labId}/sessions/\${before.id}/\${action}\`;</span></span>
<span class="line"><span>  const conflict = await fetch(path, {</span></span>
<span class="line"><span>    method: &#39;POST&#39;,</span></span>
<span class="line"><span>    headers: {</span></span>
<span class="line"><span>      &#39;content-type&#39;: &#39;application/json&#39;,</span></span>
<span class="line"><span>      &#39;x-csrf-token&#39;: identity.csrf_token,</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    body: JSON.stringify({ expected_revision: before.revision - 1 }),</span></span>
<span class="line"><span>  });</span></span>
<span class="line"><span>  if (conflict.status !== 409)</span></span>
<span class="line"><span>    throw new Error(\`Expected conflict 409, received \${conflict.status}\`);</span></span>
<span class="line"><span>  const denied = await fetch(path, {</span></span>
<span class="line"><span>    method: &#39;POST&#39;,</span></span>
<span class="line"><span>    headers: { &#39;content-type&#39;: &#39;application/json&#39; },</span></span>
<span class="line"><span>    body: JSON.stringify({ expected_revision: before.revision }),</span></span>
<span class="line"><span>  });</span></span>
<span class="line"><span>  if (denied.status !== 403)</span></span>
<span class="line"><span>    throw new Error(\`Expected CSRF refusal 403, received \${denied.status}\`);</span></span>
<span class="line"><span>  const after = await read();</span></span>
<span class="line"><span>  if (</span></span>
<span class="line"><span>    after?.id !== before.id ||</span></span>
<span class="line"><span>    after.revision !== before.revision ||</span></span>
<span class="line"><span>    after.status !== before.status</span></span>
<span class="line"><span>  )</span></span>
<span class="line"><span>    throw new Error(</span></span>
<span class="line"><span>      &#39;Session changed during the check. Stop other controls and retry.&#39;,</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>  console.log({</span></span>
<span class="line"><span>    conflict: conflict.status,</span></span>
<span class="line"><span>    denied: denied.status,</span></span>
<span class="line"><span>    unchanged: true,</span></span>
<span class="line"><span>    session_id: after.id,</span></span>
<span class="line"><span>  });</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>Expect <code>{ conflict: 409, denied: 403, unchanged: true, session_id: ... }</code>. The first request uses a stale revision. The second omits CSRF. Neither changes the Session. The browser and a valid <code>lab:full</code> Agent use the same Lab policy. A Core machine credential is independent. It can only use its dedicated Session admission contract.</p><p>The dialog shows conflicts, denied access, unavailable source, and offline state. It retains choices. <strong>Retry</strong> reads current authority and reconnects observation. It does not replay Start, Reset, or another accepted action.</p><h2 id="interrupt-and-finish" tabindex="-1">Interrupt and finish <a class="header-anchor" href="#interrupt-and-finish" aria-label="Permalink to &quot;Interrupt and finish&quot;">​</a></h2><p>Stop <code>pnpm dev</code> with Ctrl+C during a Session. Restart with the same command and data directory. The previous Session reads <strong>Session interrupted</strong>. Explicitly Start a new Session. Restart never resumes an old experiment or replays actions.</p><p>If Python is unavailable, Start reports source failure or an interrupted Session. Check the configured executable, restart the service, and Retry. The service uses finite acknowledgement and motion-loss deadlines. Missing acknowledgement, lost heartbeat, or stalled running source fails closed. Deliberate Pause is exempt from running-source progress checks.</p><p>To finish, Stop the Session, close its dialog, and stop <code>pnpm dev</code>. The supervisor releases its owned source processes and sockets. Its ledgers remain under <code>.scratch/session-tutorial-data/runtime/synthetic-sources/</code>. Keep the tutorial data directory and Python environment if needed. Do not remove another worktree&#39;s processes or data.</p><p>Sources: <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/server/src/lab/sessions/service.ts" target="_blank" rel="noreferrer">Session owner</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/server/src/lab/sessions/routes.ts" target="_blank" rel="noreferrer">HTTP routes</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/sdk/src/simulation-session.ts" target="_blank" rel="noreferrer">SDK lifecycle stream</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/views/src/lab/simulation-session-controls.tsx" target="_blank" rel="noreferrer">controls</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/sdk/src/motion-buffer.ts" target="_blank" rel="noreferrer">motion buffer</a>, and <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/views/src/lab/motion-scene.ts" target="_blank" rel="noreferrer">body-to-visual correction</a>. Source parameters default to translation amplitude <code>0.45</code>, angular speed <code>1</code>, and joint amplitude <code>1</code>. Start HTTP accepts finite values from <code>0</code> to <code>10</code> for each. These mathematical trajectories do not compute physical contact.</p><p>Continue with <a href="./spatial-workbench">the spatial workbench</a>. Production Newton, durable Recording, remote ingress, and robot tasks remain separate work.</p><hr><p>Source version：<code>c80e63c8c063</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/docs/tutorials/simulation-session.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,35)])])}const g=e(i,[["render",o]]);export{u as __pageData,g as default};
